def with_duplicate_colors(grid):
    out=base_ns['transform'](grid)
    # Recompute marker targets and color targets generated more than once blue.
    h,w=len(grid),len(grid[0]); color=next(iter({v for row in grid for v in row if v!=7}))
    pats=[(((0,0),(1,-1),(1,1)),(-5,0)),(((0,0),(-1,-1),(-1,1)),(5,0)),(((0,0),(-1,1),(1,1)),(0,-5)),(((0,0),(-1,-1),(1,-1)),(0,5)),(((0,0),(0,1),(1,0)),(-5,-5)),(((0,0),(0,-1),(1,0)),(-5,5)),(((0,0),(0,1),(-1,0)),(5,-5)),(((0,0),(0,-1),(-1,0)),(5,5))]
    from collections import Counter
    hits=Counter()
    for r in range(h):
     for c in range(w):
      if grid[r][c]==color:
       for cells,(dr,dc) in pats:
        if all(0<=r+a<h and 0<=c+b<w and grid[r+a][c+b]==color for a,b in cells):
         if 0<=r+dr<h and 0<=c+dc<w: hits[(r+dr,c+dc)]+=1
    for (r,c),n in hits.items():
     if n>1: out[r][c]=1
